"""LeIsaac task: SO-101 lifts a takeout box generated by Lux3D.

Copied into leisaac/source/leisaac/leisaac/tasks/ by setup_instance.sh; LeIsaac registers it on import.
Scenes are built locally by build_takeout_box_usd.py and synced to $LEISAAC_ASSETS_ROOT/scenes/.
"""
from pathlib import Path

import isaaclab.sim as sim_utils
import torch
from isaaclab.assets import AssetBaseCfg
from isaaclab.managers import ObservationGroupCfg as ObsGroup
from isaaclab.managers import ObservationTermCfg as ObsTerm
from isaaclab.managers import SceneEntityCfg
from isaaclab.managers import TerminationTermCfg as DoneTerm
from isaaclab.sensors import TiledCameraCfg
from isaaclab.utils import configclass
from leisaac.tasks.lift_cube import mdp
from leisaac.utils.constant import ASSETS_ROOT
from leisaac.utils.domain_randomization import domain_randomization, randomize_object_uniform
from leisaac.utils.general_assets import parse_usd_and_create_subassets

from ..template import (
    SingleArmObservationsCfg,
    SingleArmTaskEnvCfg,
    SingleArmTaskSceneCfg,
    SingleArmTerminationsCfg,
)

SCENES_ROOT = Path(ASSETS_ROOT) / "scenes"
SMALL_SCENE_USD = str(SCENES_ROOT / "table_with_takeout_box_small" / "scene.usd")
REAL_SCENE_USD = str(SCENES_ROOT / "table_with_takeout_box" / "scene.usd")

# The box prim origin sits at its bottom face, on the table (~0.033 m above the robot base).
LIFT_HEIGHT_ABOVE_BASE_M = 0.13  # success once the box bottom is ~10 cm above the table
GRASP_DISTANCE_M = 0.05  # jaw-to-box-origin distance that still counts as "grasped"


def front_camera() -> TiledCameraCfg:
    return TiledCameraCfg(
        prim_path="{ENV_REGEX_NS}/Robot/base/front_camera",
        offset=TiledCameraCfg.OffsetCfg(
            pos=(-0.6, -0.75, 0.38), rot=(0.77337, 0.55078, -0.2374, -0.20537), convention="opengl"
        ),
        data_types=["rgb"],
        spawn=sim_utils.PinholeCameraCfg(
            focal_length=40.6, focus_distance=400.0, horizontal_aperture=38.11,
            clipping_range=(0.01, 50.0), lock_camera=True,
        ),
        width=640,
        height=480,
        update_period=1 / 30.0,
    )


@configclass
class LiftTakeoutBoxSceneCfg(SingleArmTaskSceneCfg):
    scene: AssetBaseCfg = AssetBaseCfg(
        prim_path="{ENV_REGEX_NS}/Scene", spawn=sim_utils.UsdFileCfg(usd_path=SMALL_SCENE_USD)
    )
    front: TiledCameraCfg = front_camera()
    light = AssetBaseCfg(
        prim_path="{ENV_REGEX_NS}/Light",
        spawn=sim_utils.DomeLightCfg(color=(0.75, 0.75, 0.75), intensity=1000.0),
    )


@configclass
class ObservationsCfg(SingleArmObservationsCfg):
    @configclass
    class SubtaskCfg(ObsGroup):
        pick_box = ObsTerm(
            func=mdp.object_grasped,
            params={
                "robot_cfg": SceneEntityCfg("robot"),
                "ee_frame_cfg": SceneEntityCfg("ee_frame"),
                "object_cfg": SceneEntityCfg("takeout_box"),
                "diff_threshold": GRASP_DISTANCE_M,
            },
        )

        def __post_init__(self):
            self.enable_corruption = False
            self.concatenate_terms = False

    subtask_terms: SubtaskCfg = SubtaskCfg()


@configclass
class TerminationsCfg(SingleArmTerminationsCfg):
    success = DoneTerm(
        func=mdp.cube_height_above_base,
        params={
            "cube_cfg": SceneEntityCfg("takeout_box"),
            "robot_cfg": SceneEntityCfg("robot"),
            "robot_base_name": "base",
            "height_threshold": LIFT_HEIGHT_ABOVE_BASE_M,
        },
    )


@configclass
class LiftTakeoutBoxEnvCfg(SingleArmTaskEnvCfg):
    scene: LiftTakeoutBoxSceneCfg = LiftTakeoutBoxSceneCfg(env_spacing=8.0)
    observations: ObservationsCfg = ObservationsCfg()
    terminations: TerminationsCfg = TerminationsCfg()
    task_description: str = "Pick up the takeout box and lift it off the table."
    scene_usd: str = SMALL_SCENE_USD

    def __post_init__(self) -> None:
        super().__post_init__()
        self.scene.scene = self.scene.scene.replace(spawn=sim_utils.UsdFileCfg(usd_path=self.scene_usd))
        self.viewer.eye = (-0.4, -0.6, 0.5)
        self.viewer.lookat = (0.9, 0.0, -0.3)
        self.scene.robot.init_state.pos = (0.35, -0.64, 0.01)
        parse_usd_and_create_subassets(self.scene_usd, self)
        domain_randomization(
            self,
            random_options=[
                randomize_object_uniform(
                    "takeout_box",
                    pose_range={
                        "x": (-0.05, 0.05),
                        "y": (-0.05, 0.05),
                        "z": (0.0, 0.0),
                        "yaw": (-30 * torch.pi / 180, 30 * torch.pi / 180),
                    },
                ),
            ],
        )


@configclass
class LiftTakeoutBoxRealEnvCfg(LiftTakeoutBoxEnvCfg):
    scene_usd: str = REAL_SCENE_USD
